mapper.update:
update faq_tbl set
    faq_title = #{faqTitle},
    faq_content = #{faqContent},
    faq_category = #{faqCategory}
where faq_no = #{faqNo}

mapper.select:
select m.member_id, m.member_name, m.member_nickname, m.member_email, m.member_grade, m.member_thumb, m.member_status, date_format(m.enroll_date, '%Y-%m-%d') as enrollDate, m.lock_reason, m.lock_until, -- 게시글/댓글/신고 수는 서브쿼리로 각각 카운트 (select count(*) from board_tbl b where b.writer_id = m.member_id) as boardCount, (select count(*) from board_comment_tbl c where c.board_comment_writer = m.member_id) as commentCount, (select count(*) from report_tbl r join board_tbl b on r.target_no = b.board_no where b.writer_id = m.member_id) as reportCount, (select count(*) from member_log_tbl l where l.member_id = m.member_id and l.log_action = '로그인실패' and l.log_time >= date_add(now(), interval -1 day)) as failCount, (select count(*) from member_log_tbl l where l.member_id = m.member_id and l.log_alert = '위치변경' and l.log_time >= date_add(now(), interval -1 day)) as locationChangeCount, -- 가장 최근 로그인/로그아웃 액션이 '로그인'이면 접속중, '로그아웃'이면 미접속 (case when ( select log_action from member_log_tbl where member_id = m.member_id and log_action in ('로그인', '로그아웃') order by log_time desc, member_log_no desc limit 1 ) = '로그인' then 1 else 0 end) as isOnline from member_tbl1 m
m.member_status = #{status}
and m.member_grade = #{grade}
and (m.member_id like concat('%', #{keyword}, '%') or m.member_name like concat('%', #{keyword}, '%'))
order by m.enroll_date desc

select
    member_log_no,
    log_ip,
    log_time,
    log_action,
    log_detail,
    log_device,
    log_location,
    log_result,
    log_alert
from member_log_tbl
where member_id = #{memberId}

    and log_action = #{action}


    and log_result = #{result}

order by log_time ${sort}
limit 20 offset #{start}

mapper.update:
update board_tbl set board_status =
1 2
where board_no = #{targetNo}

update board_comment_tbl set board_comment_status =

        1

where board_comment_no = #{targetNo}

update member_tbl1 set
lock_until = date_add(now(), interval 1 day), member_status = 3, lock_until = date_add(now(), interval 3 day), member_status = 3, lock_until = date_add(now(), interval 7 day), member_status = 3, member_status = 1,
lock_reason = #{lockReason} where member_id = #{targetId}

update report_tbl set
    report_status = 1
where target_no = #{targetNo} and target_type = #{targetType}
